import java.util.*;

class Solution {
    public void printNameNTimes(String name, int n) {
        printFrom(name, 0, n);
    }

    private void printFrom(String name, int count, int n) {
        if (count == n) {
            return;
        }
        System.out.println(name);
        printFrom(name, count + 1, n);
    }
}
